<script setup lang="ts">import type { SettingsRole } from '../types'; import type { SettingsScenarioName } from '../../../../mock/handlers/settings-handler'; defineProps<{ scenario: SettingsScenarioName; role: SettingsRole }>(); const emit = defineEmits<{ scenario: [SettingsScenarioName]; role: [SettingsRole] }>()</script>
<template><div class="settings-scenario"><span>原型控制</span><label>场景<select :value="scenario" @change="emit('scenario', ($event.target as HTMLSelectElement).value as SettingsScenarioName)"><option value="normal">正常</option><option value="empty">空数据</option><option value="error">服务异常</option><option value="slow">慢响应</option><option value="permission-denied">无权限</option></select></label><label>角色<select :value="role" @change="emit('role', ($event.target as HTMLSelectElement).value as SettingsRole)"><option value="super-admin">超级管理员</option><option value="finance">财务</option><option value="sales-supervisor">销售主管</option><option value="salesperson">业务员</option><option value="warehouse">仓库</option></select></label></div></template>
